functions.createDefaultCalendarEntries:
function createDefaultCalendarEntries(lines){
  const entries=[];
  const planningStart=dateFromIso("2026-07-22");
  const yearEnd=new Date(2026,11,31,12);

  lines.filter(line=>line.active).forEach(line=>{
    if(line.generation==="calendar"&&line.frequency==="weekly"){
      const lineStart=line.start?dateFromIso(line.start):new Date(planningStart);
      const start=lineStart>planningStart?lineStart:new Date(planningStart);
      const end=line.end?dateFromIso(line.end):yearEnd;

      for(let date=new Date(start);date<=end;date.setDate(date.getDate()+1)){
        if((line.preferredDays||[]).includes(date.getDay())){
          const dateKey=isoDate(date);
          entries.push(normalizeCalendarEntry({
            id:`slot-${line.id}-${dateKey}`,
            title:line.name,
            origin:"linha",
            lineId:line.id,
            natures:line.natures,
            date:dateKey,
            time:line.time||"",
            behavior:line.behavior,
            fixed:false,
            priority:"normal",
            status:"confirmado",
            note:line.description||""
          }));
        }
      }
    }

    if(line.generation==="bank"&&line.frequency==="quantity"){
      const labels=line.name==="Da Semente ao Paciente"
        ?["Cultivo","Beneficiamento/Trima","Laboratório","Acolhimento","Expedição"]
        :null;
      const total=Number(line.quantity||line.frequencyCount||0);

      for(let index=1;index<=total;index++){
        entries.push(normalizeCalendarEntry({
          id:`slot-${line.id}-${index}`,
          title:labels?.[index-1]||`${line.name} ${index}`,
          origin:"linha",
          lineId:line.id,
          number:String(index),
          natures:line.natures,
          date:"",
          behavior:line.behavior,
          priority:"normal",
          status:"sem data",
          note:line.description||""
        }));
      }
    }

    if(line.generation==="bank"&&line.frequency==="monthly_count"){
      for(let month=planningStart.getMonth();month<12;month++){
        for(let index=1;index<=Number(line.frequencyCount||1);index++){
          entries.push(normalizeCalendarEntry({
            id:`slot-${line.id}-${month}-${index}`,
            title:`${line.name} — ${MONTHS[month]} ${index}`,
            origin:"linha",
            lineId:line.id,
            number:String(index),
            natures:line.natures,
            date:"",
            behavior:line.behavior,
            priority:"normal",
            status:"sem data",
            note:line.description||"",
            targetMonth:month
          }));
        }
      }
    }
  });

  entries.push(normalizeCalendarEntry({
    id:"special-adapta-pais-2026",
    title:"Adapta Pais",
    origin:"avulso",
    natures:["Campanha","Comunidade"],
    date:"2026-08-09",
    behavior:"main",
    fixed:true,
    priority:"high",
    status:"provisório",
    note:"Especial de Dia dos Pais. A data pode ser ajustada."
  }));

  entries.push(normalizeCalendarEntry({
    id:"special-informativo-operacional",
    title:"Informativo operacional",
    origin:"informativo",
    natures:["Serviço"],
    date:"",
    behavior:"main",
    fixed:false,
    priority:"high",
    status:"sem data",
    note:"Modelo para pausa, plantão, feriado ou alteração de funcionamento."
  }));

  HOLIDAYS_2026.forEach(holiday=>{
    entries.push(normalizeCalendarEntry({
      id:`feriado-${holiday.date}`,
      title:`Informativo — ${holiday.name}`,
      origin:"informativo",
      natures:["Serviço"],
      date:holiday.date,
      behavior:"main",
      fixed:true,
      priority:"high",
      status:holiday.decision==="A definir"?"provisório":"confirmado",
      note:`${holiday.scope}. Decisão operacional: ${holiday.decision}.`,
      holiday:true,
      holidayName:holiday.name,
      holidayScope:holiday.scope,
      referenceDate:holiday.date,
      operationDecision:holiday.decision
    }));
  });

  return entries;
}

functions.holidayEmailRuleText:
function holidayEmailRuleText(holiday,value){
  if(value.expediente==="Abertura excepcional"){
    return"E-mail obrigatório: haverá abertura excepcional no feriado.";
  }
  if(holidayIsClosure(value)&&holidayIsExtended(holiday,value)){
    return"E-mail obrigatório: o fechamento ficará ligado ao fim de semana ou a uma emenda.";
  }
  return"Não gerar e-mail para este aviso.";
}

functions.holidayStorySchedule:
function holidayStorySchedule(holiday){
  const standard=[
    {
      key:"story-1",
      label:"2 dias úteis antes",
      date:holidayBusinessDayBefore(holiday.date,2)
    },
    {
      key:"story-2",
      label:"1 dia útil antes",
      date:holidayBusinessDayBefore(holiday.date,1)
    },
    {
      key:"story-3",
      label:"No feriado",
      date:holiday.date
    }
  ];

  const today=isoDate(new Date());
  if(today<standard[0].date)return standard;
  if(today>holiday.date)return[];

  const remaining=standard.filter(entry=>entry.date>today);
  return[
    {
      key:"story-now",
      label:"Publicar imediatamente",
      date:today
    },
    ...remaining
  ].filter((entry,index,list)=>
    list.findIndex(candidate=>candidate.date===entry.date)===index
  );
}

functions.holidayOperationSentence:
function holidayOperationSentence(holiday,value){
  const date=holidayLongDate(holiday.date);
  const weekdayName=holidayWeekday(holiday.date);

  if(value.expediente==="Fechado"){
    return`No feriado de ${holiday.name}, em ${date}, ${weekdayName}, estaremos fechados.`;
  }
  if(value.expediente==="Somente acolhimento fechado"){
    return`No feriado de ${holiday.name}, em ${date}, ${weekdayName}, não haverá acolhimento.`;
  }
  if(value.expediente==="Somente expedição fechada"){
    return`No feriado de ${holiday.name}, em ${date}, ${weekdayName}, a expedição estará pausada.`;
  }
  if(value.expediente==="Horário reduzido"){
    const schedule=(value.horario_escala||"").trim()||"[CONFIRMAR HORÁRIO REDUZIDO]";
    return`No feriado de ${holiday.name}, em ${date}, ${weekdayName}, estaremos online em horário especial: ${schedule}.`;
  }
  if(value.expediente==="Plantão"){
    const schedule=(value.horario_escala||"").trim()||"[CONFIRMAR HORÁRIO OU ESCALA DE PLANTÃO]";
    return`No feriado de ${holiday.name}, em ${date}, ${weekdayName}, teremos plantão: ${schedule}.`;
  }
  if(value.expediente==="Abertura excepcional"){
    return`No feriado de ${holiday.name}, em ${date}, ${weekdayName}, vamos estar por aqui.`;
  }
  return`O funcionamento da Adapta em ${date} precisa ser confirmado.`;
}

functions.holidayEmailBriefingHtml:
function holidayEmailBriefingHtml(holiday,value){
  const required=holidayEmailRequired(holiday,value);
  if(!required){
    return`<div class="block">
      <h3>E-mail aos associados</h3>
      <p>Não gerar e-mail para este aviso.</p>
    </div>`;
  }

  const subject=value.expediente==="Abertura excepcional"
    ?`A Adapta estará online no feriado de ${holiday.name}`
    :`${holiday.name}: ${holidayPublicCta(holiday,value).replace(/\.$/,"")}`;

  const body=[
    holidayOperationSentence(holiday,value),
    holidayPublicCta(holiday,value),
    holidayAvailabilityLine(value)
  ].join("\n\n");

  return`<div class="block">
    <h3>E-mail aos associados</h3>
    <p><b>Assunto sugerido:</b> ${escapeHtml(subject)}</p>
    <div class="caption">${escapeHtml(body)}</div>
  </div>`;
}

