functions.ensureFullCalendar:
function ensureFullCalendar(){
  const status=document.getElementById("calendarStatus");
  const target=document.getElementById("fullCalendar");

  if(typeof FullCalendar==="undefined"||!FullCalendar.Calendar){
    status.hidden=false;
    status.className="calendar-loading error";
    status.textContent="Não foi possível carregar o FullCalendar. Verifique a conexão com a internet e recarregue a página.";
    target.hidden=true;
    return false;
  }

  status.hidden=true;
  target.hidden=false;

  if(fullCalendarInstance)return true;

  // FullCalendar v7 Classic: toolbar e eventos usam a paleta institucional desde a instanciação.
  target.style.setProperty("--fc-classic-button", "#0A3426");
  target.style.setProperty("--fc-classic-button-border", "#0A3426");
  target.style.setProperty("--fc-classic-button-strong", "#07271D");
  target.style.setProperty("--fc-classic-button-strong-border", "#07271D");
  target.style.setProperty("--fc-classic-button-foreground", "#ffffff");
  target.style.setProperty("--fc-classic-primary", "#0A3426");
  target.style.setProperty("--fc-classic-primary-foreground", "#ffffff");
  target.style.setProperty("--fc-event-bg-color", "#0A3426");
  target.style.setProperty("--fc-event-border-color", "#0A3426");
  target.style.setProperty("--fc-event-text-color", "#ffffff");

  fullCalendarInstance=new FullCalendar.Calendar(target,{
    themeSystem:"classic",
    eventColor:"#0A3426",
    eventBackgroundColor:"#0A3426",
    eventBorderColor:"#0A3426",
    eventTextColor:"#ffffff",
    locale:"pt-br",
    firstDay:1,
    initialDate:desiredCalendarDate(),
    initialView:desiredCalendarView(),
    headerToolbar:{
      start:"title",
      end:"today prev,next dayGridMonth,multiMonthYear,listMonth"
    },
    height:"auto",
    fixedWeekCount:false,
    showNonCurrentDates:true,
    editable:true,
    eventStartEditable:true,
    eventDurationEditable:false,
    navLinks:true,
    dayMaxEvents:true,
    multiMonthMaxColumns:3,
    singleMonthMinWidth:260,
    events:fullCalendarEvents(),
    dayCellClassNames(arg){
      const classes=[];
      if(state.settings.preferredDays.includes(arg.date.getDay())){
        classes.push("adapta-preferred-day");
      }
      const count=mainCountInWeek(arg.date);
      if(count>Number(state.settings.weeklyCapacity||3))classes.push("adapta-week-over");
      else if(count===Number(state.settings.weeklyCapacity||3))classes.push("adapta-week-full");
      return classes;
    },
    dayCellDidMount(arg){
      const cell=arg.el;

      cell.addEventListener("dragenter",event=>{
        if(!activeExternalCalendarItem)return;
        event.preventDefault();
        cell.classList.add("adapta-external-drop-target");
      });

      cell.addEventListener("dragover",event=>{
        if(!activeExternalCalendarItem)return;
        event.preventDefault();
        if(event.dataTransfer)event.dataTransfer.dropEffect="move";
        cell.classList.add("adapta-external-drop-target");
      });

      cell.addEventListener("dragleave",event=>{
        if(!cell.contains(event.relatedTarget)){
          cell.classList.remove("adapta-external-drop-target");
        }
      });

      cell.addEventListener("drop",event=>{
        event.preventDefault();
        event.stopPropagation();
        cell.classList.remove("adapta-external-drop-target");

        let payload=activeExternalCalendarItem;

        if(!payload&&event.dataTransfer){
          const raw=
            event.dataTransfer.getData("application/x-adapta-calendar-item")
            ||event.dataTransfer.getData("text/plain");
          try{
            payload=raw?JSON.parse(raw):null;
          }catch(error){
            payload=null;
          }
        }

        if(!payload?.sourceType||!payload?.sourceId)return;

        const date=isoDate(arg.date);
        const changed=setUnifiedCalendarDate(
          payload.sourceType,
          payload.sourceId,
          date,
          {silent:true}
        );

        activeExternalCalendarItem=null;
        document.querySelectorAll(".adapta-external-drop-target")
          .forEach(target=>target.classList.remove("adapta-external-drop-target"));

        if(changed){
          localStorage.setItem(STORAGE_KEY,JSON.stringify(state));
          refreshWithoutCalendarRebuild();
          showToast(`Item agendado para ${formatDate(date)}.`);
        }
      });
    },
    eventDragStart(info){
      const zone=document.getElementById("calendarBankDropzone");
      if(zone)zone.classList.add("is-ready");
    },
    eventDragStop(info){
      const zone=document.getElementById("calendarBankDropzone");
      if(!zone)return;

      const rect=zone.getBoundingClientRect();
      const x=info.jsEvent?.clientX??-1;
      const y=info.jsEvent?.clientY??-1;
      const droppedInBank=
        x>=rect.left&&x<=rect.right
        &&y>=rect.top&&y<=rect.bottom;

      zone.classList.remove("is-ready");
      if(!droppedInBank)return;

      const props=info.event.extendedProps;
      const occurrenceIndex=Number(props.occurrenceIndex);

      const changed=props.sourceType==="entry"
        ?setCalendarEntryDate(props.entryId,"",{silent:true})
        :Number.isInteger(occurrenceIndex)&&occurrenceIndex>=0
          ?setHolidayStoryDate(
              props.postId,
              occurrenceIndex,
              "",
              {silent:true}
            )
          :setDate(props.postId,"",{silent:true});

      if(changed){
        localStorage.setItem(STORAGE_KEY,JSON.stringify(state));
        refreshWithoutCalendarRebuild();
        showToast("Item devolvido ao banco sem data.");
      }
    },
    eventDidMount(info){
      const props=info.event.extendedProps;
      if(props.sourceType!=="entry"||!props.posted)return;
      if(info.el.querySelector(".adapta-slot-ok"))return;
      const badge=document.createElement("span");
      badge.className="adapta-slot-ok";
      badge.setAttribute("aria-label","Postado");
      badge.innerHTML="<i></i><b>OK</b>";
      info.el.appendChild(badge);
    },
    eventClick(info){
      info.jsEvent.preventDefault();
      const props=info.event.extendedProps;
      if(props.sourceType!=="entry"){
        openDetails(props.postId);
        return;
      }
      const el=info.el;
      if(el.__adaptaSlotClickTimer){
        clearTimeout(el.__adaptaSlotClickTimer);
        el.__adaptaSlotClickTimer=null;
        setCalendarEntryPosted(props.entryId,!Boolean(props.posted));
        return;
      }
      el.__adaptaSlotClickTimer=setTimeout(()=>{
        el.__adaptaSlotClickTimer=null;
        openCalendarEntry(props.entryId);
      },340);
    },
    eventDrop(info){
      const date=info.event.startStr.slice(0,10);
      const props=info.event.extendedProps;
      const occurrenceIndex=Number(props.occurrenceIndex);

      const changed=props.sourceType==="entry"
        ?setCalendarEntryDate(props.entryId,date,{silent:true})
        :Number.isInteger(occurrenceIndex)&&occurrenceIndex>=0
          ?setHolidayStoryDate(props.postId,occurrenceIndex,date,{silent:true})
          :setDate(props.postId,date,{silent:true});

      if(changed){
        localStorage.setItem(STORAGE_KEY,JSON.stringify(state));
        refreshWithoutCalendarRebuild();
        showToast(`Data alterada para ${formatDate(date)}.`);
      }
    },
    datesSet(info){
      const current=fullCalendarInstance.getDate();
      state.settings.calendarYear=current.getFullYear();
      state.settings.calendarMonth=current.getMonth();
      state.settings.calendarMode=info.view.type==="multiMonthYear"?"annual":"monthly";
      localStorage.setItem(STORAGE_KEY,JSON.stringify(state));
      renderCalendarProgress();
    }
  });

  fullCalendarInstance.render();
  return true;
}

